function normalizeDiseaseQuery(value) {
    return String(value || "").toLowerCase().replace(/[\s_]+/g, " ").trim();
}

export function findPortalDiseaseReference(query, source = "") {
    const normalized = normalizeDiseaseQuery(query);
    const normalizedSource = String(source || "").toLowerCase();
    if (!normalized) return null;
    return portalDiseaseReferenceIndex.find((item) => {
        if (normalizedSource && item.source !== normalizedSource) return false;
        const candidates = [item.sourceId, item.rawId, item.name, item.label].map(normalizeDiseaseQuery);
        return candidates.some((candidate) => candidate === normalized || candidate.includes(normalized));
    }) || null;
}

export function portalDiseaseReferenceSuggestions(source = "", limit = 200, query = "") {
    const normalizedSource = String(source || "").toLowerCase();
    const normalizedQuery = normalizeDiseaseQuery(query);
    return portalDiseaseReferenceIndex
        .filter((item) => !normalizedSource || item.source === normalizedSource)
        .filter((item) => {
            if (!normalizedQuery) return true;
            const candidates = [item.sourceId, item.rawId, item.name, item.label].map(normalizeDiseaseQuery);
            return candidates.some((candidate) => candidate.includes(normalizedQuery));
        })
        .slice(0, limit);
}
